-- 1) Clean up (safe for re-run)
DROP SCHEMA IF EXISTS coffee CASCADE;
CREATE SCHEMA coffee;

-- 2) Core tables
CREATE TABLE coffee.customer (
  customer_id  BIGSERIAL PRIMARY KEY,
  full_name    VARCHAR(120) NOT NULL,
  phone        VARCHAR(30),
  email        VARCHAR(120) UNIQUE,
  member_since DATE DEFAULT CURRENT_DATE
);

CREATE TABLE coffee.employee (
  employee_id BIGSERIAL PRIMARY KEY,
  full_name   VARCHAR(120) NOT NULL,
  position    VARCHAR(60) NOT NULL, -- e.g., Barista, Cashier, Manager
  hire_date   DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE coffee.category (
  category_id BIGSERIAL PRIMARY KEY,
  category_name VARCHAR(80) NOT NULL UNIQUE
);

CREATE TABLE coffee.product (
  product_id   BIGSERIAL PRIMARY KEY,
  category_id  BIGINT NOT NULL REFERENCES coffee.category(category_id),
  product_name VARCHAR(120) NOT NULL,
  price        NUMERIC(10,2) NOT NULL CHECK (price >= 0),
  is_active    BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE(category_id, product_name)
);

CREATE TABLE coffee."order" (
  order_id     BIGSERIAL PRIMARY KEY,
  order_ts     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  customer_id  BIGINT REFERENCES coffee.customer(customer_id),
  employee_id  BIGINT NOT NULL REFERENCES coffee.employee(employee_id),
  status       VARCHAR(20) NOT NULL DEFAULT 'PAID' CHECK (status IN ('PENDING','PAID','CANCELLED')),
  note         TEXT
);

CREATE TABLE coffee.order_item (
  order_item_id BIGSERIAL PRIMARY KEY,
  order_id      BIGINT NOT NULL REFERENCES coffee."order"(order_id) ON DELETE CASCADE,
  product_id    BIGINT NOT NULL REFERENCES coffee.product(product_id),
  qty           INTEGER NOT NULL CHECK (qty > 0),
  unit_price    NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0),
  discount      NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (discount >= 0)
);

CREATE TABLE coffee.payment (
  payment_id BIGSERIAL PRIMARY KEY,
  order_id   BIGINT NOT NULL UNIQUE REFERENCES coffee."order"(order_id) ON DELETE CASCADE,
  method     VARCHAR(20) NOT NULL CHECK (method IN ('CASH','CARD','TRANSFER','QR')),
  amount     NUMERIC(10,2) NOT NULL CHECK (amount >= 0),
  paid_ts    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 3) Helpful indexes
CREATE INDEX idx_order_ts ON coffee."order"(order_ts);
CREATE INDEX idx_order_customer ON coffee."order"(customer_id);
CREATE INDEX idx_order_employee ON coffee."order"(employee_id);
CREATE INDEX idx_item_order ON coffee.order_item(order_id);
CREATE INDEX idx_item_product ON coffee.order_item(product_id);

