-- 6) Views used in labs (read-only reporting)
CREATE OR REPLACE VIEW coffee.v_order_summary AS
SELECT
  o.order_id,
  o.order_ts,
  o.status,
  COALESCE(c.full_name, 'Guest') AS customer_name,
  e.full_name AS cashier_name,
  SUM(oi.qty * oi.unit_price - oi.discount) AS gross_amount
FROM coffee."order" o
LEFT JOIN coffee.customer c ON c.customer_id = o.customer_id
JOIN coffee.employee e ON e.employee_id = o.employee_id
JOIN coffee.order_item oi ON oi.order_id = o.order_id
GROUP BY o.order_id, o.order_ts, o.status, COALESCE(c.full_name, 'Guest'), e.full_name;

CREATE OR REPLACE VIEW coffee.v_daily_sales AS
SELECT
  DATE(o.order_ts) AS sales_date,
  COUNT(DISTINCT o.order_id) FILTER (WHERE o.status='PAID') AS paid_orders,
  SUM(oi.qty * oi.unit_price - oi.discount) FILTER (WHERE o.status='PAID') AS paid_revenue
FROM coffee."order" o
JOIN coffee.order_item oi ON oi.order_id = o.order_id
GROUP BY DATE(o.order_ts)
ORDER BY sales_date;

